export async function withExponentialBackoff<T>(
  operation: () => Promise<T>,
  shouldRetry: (value: T) => boolean,
): Promise<T> {
  let delayMs = 100;

  for (let attempt = 0; ; attempt += 1) {
    const value = await operation();

    if (attempt === 2 || !shouldRetry(value)) {
      return value;
    }

    await new Promise((resolve) => setTimeout(resolve, delayMs));
    delayMs *= 2;
  }
}
export type Webhook = {
  url: string;
  body: string;
};

export async function dispatchWebhook(webhook: Webhook): Promise<Response> {
  return fetch(webhook.url, {
    method: "POST",
    body: webhook.body,
  });
}

